<script setup>
import {computed,ref} from 'vue';
import {Head,router,usePage} from '@inertiajs/vue3';
import {Bot,BrainCircuit,Database,FileCode2,Bug,LayoutDashboard,History,Send,ShieldCheck,Trash2,CheckCircle2} from 'lucide-vue-next';
const page=usePage();
const props=defineProps({runs:{type:Array,default:()=>[]},config:{type:Object,default:()=>({demo_mode:true,model:'gpt-5.6-luna'})}});
const taskType=ref('requirement'),title=ref(''),requirement=ref(''),processing=ref(false),selectedRun=ref(null),activeView=ref('workspace');
const taskOptions=[['requirement','Requirement Analysis'],['database','Database Schema'],['crud','Laravel CRUD'],['api','API Planning'],['bug','Bug Analysis'],['vue','Vue Component'],['documentation','Documentation'],['testing','Testing Checklist']];
const examples={requirement:'I need an LMS with Admin, Instructor and Student roles, courses, lessons, quizzes, payments and student progress.',database:'Design a database for a service booking platform with customers, services, bookings, staff and payments.',crud:'Create a Product CRUD with name, SKU, price, stock quantity, category, image and active status.',api:'Create REST APIs for customer management with search, filtering, pagination and validation.',bug:'SQLSTATE[42S22]: Column not found: 1054 Unknown column status in where clause. The dashboard request fails.',vue:'Create a responsive customer table with search, filters, pagination, loading, empty state and delete confirmation.',documentation:'Write technical documentation for a Laravel 12 + Vue 3 + Inertia customer management module.',testing:'Create a complete test checklist for an authenticated CRUD application with roles and permissions.'};
const flashRun=computed(()=>page.props.flash?.ai_run||null),errors=computed(()=>page.props.errors||{}),outputRun=computed(()=>selectedRun.value||flashRun.value),recentRuns=computed(()=>props.runs||[]);
function useExample(type=taskType.value){requirement.value=examples[type];title.value=taskOptions.find(x=>x[0]===type)?.[1]||'';}
function runEmployee(){if(requirement.value.trim().length<10||processing.value)return;processing.value=true;router.post('/ai-employee/run',{task_type:taskType.value,title:title.value,requirement:requirement.value},{preserveScroll:true,onSuccess:()=>selectedRun.value=null,onFinish:()=>processing.value=false});}
function showRun(run){selectedRun.value=run} function deleteRun(run){if(!confirm('Delete this run?'))return;router.delete(`/ai-runs/${run.id}`,{preserveScroll:true});if(selectedRun.value?.id===run.id)selectedRun.value=null}
</script>
<template><Head title="AI Employee Dashboard"/><div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">D</div><div><h1>DevPilot AI</h1><small>Web Dev Employee</small></div></div><div class="nav-label">Workspace</div><button class="nav-item" :class="{active:activeView==='workspace'}" @click="activeView='workspace'"><LayoutDashboard :size="16"/> AI Workspace</button><button class="nav-item" :class="{active:activeView==='history'}" @click="activeView='history'"><History :size="16"/> Run History <span class="nav-count">{{recentRuns.length}}</span></button><button class="nav-item" :class="{active:activeView==='verification'}" @click="activeView='verification'"><ShieldCheck :size="16"/> Verification</button><button class="nav-item" :class="{active:activeView==='submission'}" @click="activeView='submission'"><FileCode2 :size="16"/> Task 02 Submission</button><div class="sidebar-footer"><strong style="color:#aeb6c6">Human-in-the-loop</strong><br>AI drafts. Developer reviews, tests and approves.</div></aside><main class="main"><div class="topbar"><div><div class="eyebrow">AI Employee</div><h2>{{activeView==='workspace'?'Development Command Center':activeView==='history'?'Run History':activeView==='verification'?'Human Verification': 'Task 02 Submission'}}</h2></div><div class="status-pill"><span class="dot"></span>{{config.demo_mode?'Demo mode':'Live AI'}}</div></div><template v-if="activeView==='workspace'"><section class="hero"><div class="hero-grid"><div><h3>Build faster. Verify everything.</h3><p>Turn requirements, database ideas, API tasks, bugs and Vue requests into structured development output. The AI accelerates repetitive work while the developer keeps final control.</p></div><div class="stats"><div class="stat"><strong>{{recentRuns.length}}</strong><span>Saved runs</span></div><div class="stat"><strong>8</strong><span>Employee skills</span></div><div class="stat"><strong>{{config.demo_mode?'Demo':'Live'}}</strong><span>AI provider</span></div></div></div></section><div class="workspace"><section class="card"><div class="card-head"><h4>Assign a development task</h4><span>Model: {{config.model}}</span></div><div class="card-body"><div v-if="errors.ai" class="error">{{errors.ai}}</div><div class="field"><label>Employee skill</label><select v-model="taskType"><option v-for="item in taskOptions" :key="item[0]" :value="item[0]">{{item[1]}}</option></select></div><div class="field"><label>Task title</label><input v-model="title" placeholder="e.g. LMS requirement analysis"></div><div class="field"><label>Requirement / error / development context</label><textarea v-model="requirement" placeholder="Describe what you need the AI Employee to do..."></textarea><div class="quick-grid"><button v-for="item in taskOptions.slice(0,4)" :key="item[0]" class="quick" @click="taskType=item[0];useExample(item[0])">{{item[1]}}</button></div></div><button class="primary" :disabled="processing||requirement.trim().length<10" @click="runEmployee"><span v-if="processing">Running AI Employee…</span><span v-else><Send :size="14" style="vertical-align:-2px"/> Run Employee</span></button></div></section><section class="card"><div class="card-head"><h4>Employee output</h4><span v-if="outputRun">{{outputRun.mode}} · {{outputRun.duration_ms}}ms</span></div><div class="card-body output"><div v-if="!outputRun" class="empty"><div><div class="empty-icon"><Bot :size="25"/></div><strong style="color:#aeb6c6">No output yet</strong><p>Give DevPilot a real development task to generate an implementation plan.</p></div></div><div v-else class="markdown"><div style="display:flex;gap:8px;align-items:center;margin-bottom:15px;color:#6ee7b7;font-size:11px"><CheckCircle2 :size="14"/> Output generated — human verification required</div>{{outputRun.output}}</div></div></section></div></template><template v-else-if="activeView==='history'"><section class="card run-list"><div class="history-head"><div><h4>Saved employee runs</h4><small>{{recentRuns.length}} of the latest saved tasks · open a task to view its output.</small></div><button class="quick" @click="activeView='workspace'">+ New task</button></div><div v-if="recentRuns.length===0" class="empty"><div><strong>No saved runs yet</strong><p>Run a real task from AI Workspace to build your evidence.</p></div></div><div v-for="run in recentRuns" :key="run.id" class="run-item"><div class="run-icon"><Bot :size="16"/></div><div class="run-main" @click="showRun(run);activeView='workspace'"><strong>{{run.title}}</strong><small>{{run.task_type}} · {{new Date(run.created_at).toLocaleString()}} · {{run.duration_ms||0}}ms</small></div><span class="mode">{{run.mode}}</span><button class="clear-btn" @click="deleteRun(run)" title="Delete"><Trash2 :size="14"/></button></div></section></template><template v-else-if="activeView==='verification'"><section class="hero"><h3>Review every draft before use</h3><p>AI output is a draft. Mark each review step complete for every task, then record actual before and after times in your submission notes.</p></section><section class="card"><div class="card-head"><h4>Human review checklist</h4><span>Use for every saved run</span></div><div class="card-body checklist"><label v-for="step in ['Check the output against the original request and note missing requirements.','Verify framework APIs, paths, schema assumptions and facts against the project.','Review validation, permissions, privacy, security and failure cases.','Implement the approved changes and run relevant checks yourself.','Record actual manual time, AI-assisted time, quality, mistakes and human edits.']" :key="step" class="check-row"><input type="checkbox"><span>{{step}}</span></label></div></section><section class="card run-list"><div class="history-head"><div><h4>Evidence progress</h4><small>Five distinct real tasks are required for the final challenge.</small></div><span class="mode">{{Math.min(recentRuns.length,5)}} / 5 saved</span></div><div class="card-body"><p>{{recentRuns.length<5?'Keep using separate real tasks and save each AI output. Demo mode outputs are templates and should be identified as demos.':'Five saved runs are available. Confirm that each represents a distinct real task and add your measured comparison before submission.'}}</p><button class="primary" @click="activeView='history'">Review saved evidence</button></div></section></template><template v-else><section class="hero"><h3>DevPilot — AI Web Development Employee</h3><p><b>Problem:</b> Repeatedly turning web development requests into plans, schemas, API outlines, bug triage and test checklists is slow and easy to do inconsistently.</p></section><div class="info-grid"><section class="card info-card"><h4>Manual workflow</h4><p>Clarify the request → inspect project conventions → design data, routes and UI states → check security and edge cases → write the plan → implement and test.</p></section><section class="card info-card"><h4>AI workflow</h4><p>Choose a skill → provide concrete context and acceptance criteria → generate and save a draft → human verifies facts and risks → implement, test and approve.</p></section><section class="card info-card"><h4>Tools</h4><p>Laravel + PHP for validation and persistence; Vue 3 + Inertia for the dashboard; OpenAI Responses API in live mode; local demo generator when credentials are unavailable.</p></section><section class="card info-card"><h4>Prompt</h4><p>You are DevPilot AI, a senior Laravel 12 + Vue 3 + Inertia.js web-development employee. Return practical implementation-ready output. Never claim tests you did not run. State assumptions, implementation steps, edge cases, security, testing and human verification. Task type: selected skill.</p></section><section class="card info-card"><h4>Before vs after</h4><p>For each of five real tasks, compare manual minutes with AI input + generation + human review minutes. Record quality, AI mistakes, time saved, and work that must remain with a human. Do not treat estimates or generic demo output as measured results.</p></section><section class="card info-card"><h4>Limitations and future plan</h4><p>Demo output is a generic template. Live AI sees only supplied context and cannot inspect this repository or execute code. Next: complete five distinct real tasks, measure timings, review accuracy, then consider repository context and per-user retention controls.</p></section></div><section class="card run-list"><div class="history-head"><div><h4>Challenge evidence</h4><small>Saved outputs: {{recentRuns.length}} / 5 minimum</small></div><button class="quick" @click="activeView='workspace'">Create an output</button></div><div class="card-body"><p>{{recentRuns.length<5?'The app cannot honestly fill in real task outputs or measured time savings for you. Save five distinct tasks, then record observed results.':'Five saved outputs are available. Review that they are distinct real tasks and complete your measured before/after comparison.'}}</p></div></section></template></main></div></template>
